/* ------ Contract Enforcement ------*/

always @(posedge in_clock) begin 
    if (in_reset ) begin 
        gate_stall_signal <= 0;
        gold_stall_signal <= 0;
        commit_deviation <= 0;
        invalid_program <= 0;
        

    end else begin 
        if (!gold_stall_signal && !gate_stall_signal) begin 

